// JWKS cache example
const jwksCache = new Map();
async function getKeys(kid){
  const cached = jwksCache.get(kid);
  if (cached && !isExpired(cached)) {
    return cached.keys;
  }
  const keys = await fetchJWKS();
  jwksCache.set(kid, { keys, timestamp: Date.now() });
  return keys;
}
